#!/bin/sh
# Deja la demo en su estado inicial: hitos m2, m3, m5 y m6 pendientes, sin eventos ni facturas nuevas, las lecturas de telemetría que llegaron por la API de ingesta o el simulador (id > 4200; las 4.200 del Excel no se tocan) y solo los 4 usuarios de demostración con su rol, en español y con el tema «system».
# Solo toca los datos de DEMOSTRACIÓN. Usa el superusuario de PostgreSQL del contenedor local.
set -e
cd "$(dirname "$0")/.."
. ./.env
psqlc() { docker compose exec -T -e PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" postgres psql -h localhost -U "$POSTGRES_ADMIN_USER" -d "$1" -Atc "$2" >/dev/null; }
psqlc projects "DELETE FROM milestones WHERE id LIKE 'm-%'; DELETE FROM projects WHERE id LIKE 'p-%'; UPDATE milestones SET status='pending', approved_at=NULL, approved_by=NULL WHERE id IN ('m2','m3','m5','m6'); DELETE FROM outbox_events; DELETE FROM project_team;"
psqlc identity "DELETE FROM refresh_tokens; DELETE FROM users WHERE email NOT IN ('laura.rios@nexus.example','andres.mora@nexus.example','camila.soto@nexus.example','diana.vega@nexus.example'); UPDATE users SET role='project_lead', language='es', theme='system' WHERE email='laura.rios@nexus.example'; UPDATE users SET role='billing_analyst', language='es', theme='system' WHERE email='andres.mora@nexus.example'; UPDATE users SET role='sales', language='es', theme='system' WHERE email='camila.soto@nexus.example'; UPDATE users SET role='manager', language='es', theme='system' WHERE email='diana.vega@nexus.example';"
# Los documentos electrónicos no se pueden borrar (la base lo impide); el reinicio de la demo lo declara a propósito, solo en esta sesión.
psqlc billing "UPDATE invoices SET project_id = CASE number WHEN 'INV-0101' THEN 'p1' ELSE 'p2' END WHERE number IN ('INV-0101', 'INV-0102'); DELETE FROM contracts; SET erp.allow_payment_delete = on; DELETE FROM payments; SET erp.allow_einvoice_delete = on; DELETE FROM einvoice_deliveries; DELETE FROM electronic_invoices; UPDATE einvoice_numbering SET next_number = range_from WHERE id = 1; DELETE FROM customers; INSERT INTO customers (id, key, name, nit, dv, email, address, city) VALUES (gen_random_uuid(), 'banco andino (example)', 'Banco Andino (example)', '900000001', 2, 'cuentas@banco-andino.example', 'Carrera 7 # 71-21', 'Bogotá'), (gen_random_uuid(), 'retail norte (example)', 'Retail Norte (example)', '900000002', 1, 'facturas@retail-norte.example', 'Calle 10 # 4-33', 'Barranquilla'), (gen_random_uuid(), 'pyme sur (example)', 'Pyme Sur (example)', '900000003', 7, 'contabilidad@pyme-sur.example', 'Avenida 5N # 23-40', 'Cali'); UPDATE invoices SET issued_at = created_at, due_date = created_at + interval '30 days' WHERE number IN ('INV-0101','INV-0102'); UPDATE invoices SET client_name = CASE number WHEN 'INV-0101' THEN 'Banco Andino (example)' ELSE 'Retail Norte (example)' END WHERE number IN ('INV-0101','INV-0102'); DELETE FROM invoices WHERE number NOT IN ('INV-0101','INV-0102'); DELETE FROM processed_events; DELETE FROM outbox_events; SELECT setval('invoice_number_seq', 103, false);"
psqlc analytics "SET erp.allow_audit_delete = on; DELETE FROM audit_entries; UPDATE milestone_facts SET overdue_at = NULL, overdue_days = NULL, paid_cop = 0; DELETE FROM milestone_facts WHERE milestone_id NOT IN ('m1','m2','m3','m4','m5','m6'); INSERT INTO milestone_facts (milestone_id, project_id, project_name, milestone_name, amount_cop, created_at) VALUES ('m2','p1','Branch network upgrade','Link redundancy design',18500000,'2026-10-01T12:00:00Z'), ('m3','p1','Branch network upgrade','Cutover',25000000,'2026-10-01T12:00:00Z'), ('m5','p2','Retail POS integration','Pilot in 3 stores',14200000,'2026-10-01T12:00:00Z'), ('m6','p3','SME cloud migration','Inventory of workloads',7500000,'2026-10-01T12:00:00Z') ON CONFLICT (milestone_id) DO UPDATE SET project_id=EXCLUDED.project_id, project_name=EXCLUDED.project_name, milestone_name=EXCLUDED.milestone_name, amount_cop=EXCLUDED.amount_cop, created_at=EXCLUDED.created_at, approved_by=NULL, approved_at=NULL, invoice_number=NULL, invoice_status=NULL, tax_cop=NULL, total_cop=NULL, drafted_at=NULL, issued_at=NULL; DELETE FROM processed_events; DELETE FROM activity_entries;"
psqlc operations "DELETE FROM work_orders; DELETE FROM network_devices WHERE source_order IS NOT NULL; DELETE FROM iot_readings WHERE id > 4200; DELETE FROM outbox_events; UPDATE iot_devices d SET alert_state = CASE l.status WHEN 'ALERT' THEN 'alert' WHEN 'WARNING' THEN 'warning' ELSE 'normal' END, alert_state_at = l.recorded_at FROM (SELECT DISTINCT ON (device_id) device_id, status, recorded_at FROM iot_readings ORDER BY device_id, recorded_at DESC) l WHERE l.device_id = d.id;"
psqlc notifications "DELETE FROM notification_reads; DELETE FROM notifications; DELETE FROM processed_events;"
psqlc capacity "UPDATE engineers SET daily_cost_cop = (ARRAY[450000,520000,600000,380000,360000,480000])[(right(id::text, 1))::int] WHERE id::text LIKE '11111111-%'; DELETE FROM outbox_events; DELETE FROM allocations; DELETE FROM engineers WHERE id::text NOT LIKE '11111111-%'; INSERT INTO allocations (engineer_id, project_name, percent, start_date, end_date) SELECT e.id, v.p, v.pc, current_date + v.s, current_date + v.e FROM (VALUES ('11111111-1111-4111-8111-111111111101'::uuid,'Branch network upgrade',60,-10,40),('11111111-1111-4111-8111-111111111101','Retail POS integration',30,5,30),('11111111-1111-4111-8111-111111111102','SME cloud migration',80,-5,60),('11111111-1111-4111-8111-111111111103','Branch network upgrade',40,-3,25),('11111111-1111-4111-8111-111111111104','Retail POS integration',50,-20,15),('11111111-1111-4111-8111-111111111104','SME cloud migration',50,-2,20),('11111111-1111-4111-8111-111111111106','SME cloud migration',25,0,45)) AS v(id,p,pc,s,e) JOIN engineers e ON e.id = v.id;"
psqlc procurement "DELETE FROM equipment_installs; DELETE FROM supplier_items; INSERT INTO supplier_items (supplier_id, item_id, ref_price_cop, lead_days) VALUES ('22222222-2222-4222-8222-222222222201','33333333-3333-4333-8333-333333333303',2400000,5),('22222222-2222-4222-8222-222222222201','33333333-3333-4333-8333-333333333301',120000,5),('22222222-2222-4222-8222-222222222201','33333333-3333-4333-8333-333333333302',180000,5),('22222222-2222-4222-8222-222222222202','33333333-3333-4333-8333-333333333301',95000,10),('22222222-2222-4222-8222-222222222202','33333333-3333-4333-8333-333333333302',165000,12); UPDATE suppliers SET tender_ref = NULL, valid_until = NULL; UPDATE suppliers SET tender_ref = 'LIC-2026-014', valid_until = '2027-06-30' WHERE id = '22222222-2222-4222-8222-222222222202'; DELETE FROM stock_counts; DELETE FROM outbox_events; DELETE FROM purchase_orders; DELETE FROM alert_suggestions; DELETE FROM processed_events; DELETE FROM suppliers WHERE id::text NOT LIKE '22222222-%'; DELETE FROM items WHERE id::text NOT LIKE '33333333-%'; UPDATE items SET on_hand = CASE id::text WHEN '33333333-3333-4333-8333-333333333301' THEN 8 WHEN '33333333-3333-4333-8333-333333333302' THEN 3 ELSE 2 END; SET erp.allow_movement_delete = on; DELETE FROM stock_movements; INSERT INTO stock_movements (item_id, item_name, delta, on_hand_after, source, reason) SELECT id, name, on_hand, on_hand, 'opening', 'Saldo inicial' FROM items WHERE on_hand > 0;"
# Las asignaciones sembradas no publicaron eventos: se copian a las tablas derivadas (equipo del proyecto y rentabilidad) como si los avisos ya hubieran llegado.
ROWS=$(docker compose exec -T -e PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" postgres psql -h localhost -U "$POSTGRES_ADMIN_USER" -d capacity -Atc "SELECT a.id, e.name, a.project_name, a.percent, a.start_date, a.end_date, COALESCE(e.daily_cost_cop::text, 'NULL') FROM allocations a JOIN engineers e ON e.id = a.engineer_id WHERE e.id::text LIKE '11111111-%' ORDER BY a.id")
TEAM="DELETE FROM project_team; DELETE FROM removed_allocations;"; FACTS="DELETE FROM allocation_facts; DELETE FROM removed_allocation_marks;"
OLDIFS=$IFS; IFS='
'
for r in $ROWS; do
  IFS='|' read -r id name proj pct s e cost <<EOF
$r
EOF
  nm=$(printf '%s' "$name" | sed "s/'/''/g"); pj=$(printf '%s' "$proj" | sed "s/'/''/g")
  TEAM="$TEAM INSERT INTO project_team VALUES ('$id','$nm','$pj',$pct,'$s','$e',now());"
  FACTS="$FACTS INSERT INTO allocation_facts VALUES ('$id','$pj','$nm',$pct,'$s','$e',$cost,now());"
done
IFS=$OLDIFS
psqlc projects "$TEAM"
psqlc analytics "$FACTS"
echo "Demo reiniciada: 4 hitos pendientes (m2, m3, m5, m6) y 2 facturas emitidas (INV-0101, INV-0102)."
